export const DIGEST_SCHEMA_SQL=`CREATE TABLE digest_requests(id TEXT PRIMARY KEY,content_id INTEGER NOT NULL REFERENCES contents(id),state TEXT NOT NULL,generation INTEGER NOT NULL,requested_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,completed_at INTEGER,scope_json TEXT NOT NULL,synthetic INTEGER NOT NULL,candidate INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX digest_effective_request ON digest_requests(content_id) WHERE state NOT IN ('cancelled','complete','failed','result-unknown');
CREATE TABLE digest_stages(request_id TEXT NOT NULL REFERENCES digest_requests(id),name TEXT NOT NULL,state TEXT NOT NULL,required INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,error TEXT,result_sha TEXT,result_json TEXT,config_json TEXT,input_sha TEXT,run_id TEXT,reused INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(request_id,name));
CREATE TABLE digest_stage_cache(name TEXT NOT NULL,input_sha TEXT NOT NULL,config_sha TEXT NOT NULL,synthetic INTEGER NOT NULL,result_sha TEXT NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(name,input_sha,config_sha,synthetic));
CREATE TABLE digest_library(content_id INTEGER PRIMARY KEY REFERENCES contents(id),active INTEGER NOT NULL,legacy INTEGER NOT NULL,source TEXT NOT NULL DEFAULT 'ai',entered_at INTEGER NOT NULL,completed_at INTEGER,last_reviewed_at INTEGER,removed_at INTEGER,request_id TEXT,candidate INTEGER NOT NULL DEFAULT 0,synthetic INTEGER NOT NULL DEFAULT 0,bundle_json TEXT,artifact_json TEXT);
CREATE TABLE digest_candidates(id TEXT PRIMARY KEY,request_id TEXT NOT NULL UNIQUE REFERENCES digest_requests(id),content_id INTEGER NOT NULL REFERENCES contents(id),bundle_json TEXT NOT NULL,artifact_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE digest_calls(run_id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES digest_requests(id),generation INTEGER NOT NULL,stage TEXT NOT NULL,input_sha TEXT NOT NULL,config_json TEXT NOT NULL,started_at INTEGER NOT NULL);
CREATE INDEX digest_request_content ON digest_requests(content_id,requested_at DESC);`;
export function createDigestSchema(db:Database.Database):void{db.exec(DIGEST_SCHEMA_SQL);db.prepare(`INSERT INTO digest_library(content_id,active,legacy,source,entered_at,completed_at,last_reviewed_at,removed_at,request_id,candidate) SELECT id,1,1,'legacy',digested_at,NULL,last_reviewed_at,NULL,NULL,0 FROM contents WHERE digested_at IS NOT NULL`).run();}
