  artifact(id:number):DigestArtifactResult{this.content(id);const library=this.db.prepare('SELECT * FROM digest_library WHERE content_id=?').get(id) as Row|undefined;if(!library?.artifact_json||!library.bundle_json||!library.request_id)return{state:'not-ready',reason:library?.legacy?'历史入库记录尚无自动成稿，可继续手工整理和导出':'尚未完成内部 Markdown 成稿与附件校验'};try{const artifact=JSON.parse(library.artifact_json) as Artifact,bundle=JSON.parse(library.bundle_json) as WorkspaceBundle,request=this.requestRow(library.request_id),scope=this.scope(request);validateBundle(bundle);this.validateArtifact(artifact,bundle,scope);const published=path.join(this.resultsDir,artifact.path),markdown=artifact.files.find(f=>f.relativePath.endsWith('.md'))!;return{state:'ready',bundle,requestId:request.id,synthetic:!!library.synthetic,scopeRevisionId:artifact.scopeRevisionId,draftRevision:artifact.draftRevision,mapRevision:artifact.mapRevision,candidate:!!library.candidate,inLibrary:!!library.active,markdownText:readFileSync(boundedFile(published,markdown.relativePath),'utf8'),attachments:artifact.files.filter(f=>!f.relativePath.endsWith('.md')).map(f=>({relativePath:f.relativePath,sha256:f.sha256,mime:f.relativePath.endsWith('.jpg')?'image/jpeg':f.relativePath.endsWith('.webp')?'image/webp':'image/png'}))};}catch{return{state:'not-ready',reason:'内部成稿或附件缺失、损坏或版本不符；其他成果保留'};}}
